#!/usr/bin/env node
// Copies shared data of the ToyVerse from a checkout of TOYfoundation/toycoin into ToyPost:
//   i18n/sprachen.tsv, i18n/begriffe.tsv -> packages/shared/src/toy/i18n-data.ts
//   shared/toyverse.json (fixed values, decision 135) -> packages/shared/src/toy/toyverse-data.ts
// Usage: node tools/toy-i18n-sync.mjs [path-to-toycoin]   (default: ../toycoin)
// Both outputs are generated; do not edit them by hand.
import { readFileSync, writeFileSync } from 'node:fs';
import { join, dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { execFileSync } from 'node:child_process';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const toycoin = resolve(process.argv[2] ?? join(root, '..', 'toycoin'));
const read = (f) =>
  readFileSync(join(toycoin, 'i18n', f), 'utf8')
    .split('\n')
    .filter((l) => l.trim())
    .slice(1)
    .map((l) => l.split('|'));

const languages = read('sprachen.tsv').map(([code, name, dir, script]) => {
  if (!code || !name || !['ltr', 'rtl'].includes(dir)) throw new Error(`Bad language row: ${code}`);
  return { code, name, dir, script };
});
const glossary = read('begriffe.tsv').map(([key, de, en, explanationDe]) => ({ key, de, en, explanationDe }));
if (languages.length !== 45) throw new Error(`Expected 45 languages, found ${languages.length}`);

let rev = 'unknown';
try {
  rev = execFileSync('git', ['-C', toycoin, 'rev-parse', '--short', 'HEAD']).toString().trim();
} catch {}

const out = `// Generated by tools/toy-i18n-sync.mjs from TOYfoundation/toycoin i18n/ (commit ${rev}). Do not edit by hand.
// Decision 103 of the Toy projects: wallet, TOYPAY app and ToyScan share these 45 languages and this glossary.

export interface ToyLanguage {
  code: string;
  /** native name, e.g. "isiZulu" */
  name: string;
  dir: 'ltr' | 'rtl';
  script: string;
}

export interface ToyGlossaryEntry {
  key: string;
  de: string;
  en: string;
  explanationDe: string;
}

export const TOY_I18N_SOURCE = ${JSON.stringify({ repo: 'TOYfoundation/toycoin', commit: rev })} as const;

export const TOY_LANGUAGES = ${JSON.stringify(languages, null, 2)} as readonly ToyLanguage[];

export const TOY_GLOSSARY = ${JSON.stringify(glossary, null, 2)} as readonly ToyGlossaryEntry[];
`;
writeFileSync(join(root, 'packages/shared/src/toy/i18n-data.ts'), out);

const manifest = JSON.parse(readFileSync(join(toycoin, 'shared', 'toyverse.json'), 'utf8'));
if (manifest.schema !== 'toyverse/1') throw new Error(`Unknown toyverse.json schema: ${manifest.schema}`);
const data = `// Generated by tools/toy-i18n-sync.mjs from TOYfoundation/toycoin shared/toyverse.json (commit ${rev}). Do not edit by hand.
// Decision 135 of the ToyVerse: one source for fixed values. Amounts are decimal strings of smallest units (use BigInt).

export const TOYVERSE_SOURCE = ${JSON.stringify({ repo: 'TOYfoundation/toycoin', commit: rev })} as const;

export const TOYVERSE = ${JSON.stringify(manifest, null, 2)} as const;
`;
writeFileSync(join(root, 'packages/shared/src/toy/toyverse-data.ts'), data);
console.log(`${languages.length} languages, ${glossary.length} glossary entries, toyverse.json from ${toycoin} @ ${rev}`);
